'use strict';
const $=(q,root=document)=>root.querySelector(q);
const $$=(q,root=document)=>[...root.querySelectorAll(q)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('en-IN');
const COLORS={Low:'#66a48a',Moderate:'#d1b768',High:'#dea46c',Critical:'#d7877d'};
const TITLES={overview:'Overview',map:'Risk explorer',forecast:'Forecast & simulator',reports:'Field reports',alerts:'Alert center',sources:'Data & model',briefing:'Project briefing'};
const ICONS={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5 M9 3v16 M15 5v16',activity:'M2 12h4l3-8 5 16 3-8h5',flag:'M5 21V4 M5 4c5-5 8 5 15 0v10c-7 5-10-5-15 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',database:'M20 5c0 2-16 2-16 0s16-4 16 0v14c0 3-16 3-16 0V5 M4 12c0 3 16 3 16 0',presentation:'M3 3h18v13H3z M12 16v5 M8 21h8 M7 11l3-3 3 2 4-4',login:'M9 3H4v18h5 M12 12h10 M18 8l4 4-4 4',menu:'M3 6h18 M3 12h18 M3 18h18',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 17v.01 M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',plus:'M12 5v14 M5 12h14',refresh:'M20 7v5h-5 M4 17v-5h5 M20 12A8 8 0 0 0 6 6 M4 12a8 8 0 0 0 14 6',globe:'M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0 M2 12h20 M12 2c6 6 6 14 0 20 M12 2c-6 6-6 14 0 20',users:'M16 21v-3c0-6-14-6-14 0v3 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4c5 0 5 7 0 7 M19 14c3 0 4 3 4 7',road:'M7 2 3 22 M17 2l4 20 M12 3v4 M12 10v4 M12 17v4',rain:'M6 14a5 5 0 0 1 0-10 6 6 0 0 1 11 2 4 4 0 0 1 1 8 M7 17l-1 4 M12 17l-1 4 M17 17l-1 4',shield:'m12 2 8 3v6c0 6-8 11-8 11S4 17 4 11V5l8-3 M8 11l3 3 5-6',clock:'M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0 M12 6v6l4 2',location:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',eye:'M2 12c5-10 15-10 20 0-5 10-15 10-20 0 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M5 12h14 M14 7l5 5-5 5',layers:'m12 2 10 6-10 6L2 8l10-6 M2 12l10 6 10-6 M2 16l10 6 10-6',wifi:'M2 8a16 16 0 0 1 20 0 M5 12a11 11 0 0 1 14 0 M9 16a5 5 0 0 1 6 0 M12 20v.01',check:'M5 12l4 4L19 6',image:'M3 3h18v18H3z M3 17l6-6 4 4 3-3 5 5 M16 7h.01'};
function icon(name){return `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${ICONS[name]||ICONS.activity}"/></svg>`}
function icons(root=document){$$('[data-icon]',root).forEach(el=>el.outerHTML=icon(el.dataset.icon))}
function badge(level){return `<span class="badge ${esc(String(level).toLowerCase())}"><b class="mini-dot"></b>${esc(level)}</span>`}
let DATA=null,USER=null,MAP=null,ROUTE='overview',MODEL=null,toastTimer,activeFilters={state:'all',level:'all',query:''};
let chartTimer;
async function api(path,options={}){
 const {headers,...rest}=options;
 const res=await fetch('/api'+path,{credentials:'same-origin',...rest,headers:{'Content-Type':'application/json',...headers}});
 if(!res.ok){let msg;try{const d=await res.json();msg=typeof d.detail==='string'?d.detail:d.detail?.map(x=>x.msg).join('; ')}catch{msg='The server could not complete this request'}throw new Error(msg||`Request failed (${res.status})`)}
 return res.json();
}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000)}
function timeLabel(t){if(!t)return 'Scenario';const d=new Date(t);return Number.isNaN(d.valueOf())?t:d.toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}
function site(id){return DATA?.sites.find(s=>s.id===id)}
function authority(){return ['official','admin'].includes(USER?.role)}
function fieldsOptions(selected){return DATA.sites.map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${esc(s.name)} · ${esc(s.state)}</option>`).join('')}
function pageHead(title,sub,actions='',eyebrow='REGIONAL INTELLIGENCE'){
 return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-actions">${actions}</div></div>`;
}
function scenario(){return `<div class="scenario-banner"><span>${icon('shield')}<strong>Demonstration workspace</strong> · Pilot scenarios, illustrative terrain and synthetic model training. No official warnings are issued.</span><a href="#sources">View data provenance ↗</a></div>`}
function refreshButton(){return `<button class="button" data-action="refresh">${icon('refresh')}Refresh</button>`}
function exportButton(kind){return `<button class="button" data-action="export" data-kind="${kind}">${icon('download')}Export ${kind==='sites'?'report':'CSV'}</button>`}
function mapPanel(large=false){return `<section class="panel"><div class="panel-head"><div><h2>Regional risk intelligence</h2><p>Spatial overview of pilot locations across the North East</p></div><span class="meta"><b class="live-dot"></b>Scenario view</span></div><div class="map-toolbar"><select class="select" id="state-filter" aria-label="Filter by state"><option value="all">All 8 states</option>${[...new Set(DATA.sites.map(s=>s.state))].sort().map(s=>`<option>${esc(s)}</option>`).join('')}</select><select class="select" id="risk-filter" aria-label="Filter by risk"><option value="all">All risk levels</option>${['Critical','High','Moderate','Low'].map(s=>`<option>${s}</option>`).join('')}</select><div class="map-filter-wrap segmented"><button data-action="basemap" data-mode="terrain" class="active">Map</button><button data-action="basemap" data-mode="satellite">Satellite</button></div></div><div class="map-wrap"><div id="risk-map" class="map ${large?'large':''}" role="region" aria-label="Interactive landslide risk map"></div><div class="map-note">Illustrative road segments & risk footprints</div></div><div class="map-legend"><div class="legend-items">${Object.entries(COLORS).map(([k,v])=>`<span><b style="background:${v}"></b>${k}</span>`).join('')}</div><span>Scroll to zoom · Select a location</span></div></section>`}
function priorityPanel(){const priority=[...DATA.sites].sort((a,b)=>b.risk.score-a.risk.score).slice(0,4);return `<section class="panel"><div class="panel-head"><div><h2>Response priorities</h2><p>Locations that need attention first</p></div>${icon('flag')}</div><div class="priority-list">${priority.map((s,i)=>`<button class="priority-item" data-action="site" data-id="${s.id}" style="background:none;border-right:0;border-left:0;border-bottom:0;text-align:left;width:100%"><span class="priority-number">0${i+1}</span><span class="priority-info"><strong>${esc(s.name)}</strong><p>${esc(s.state)} <span>· ${esc(s.road)}</span></p>${badge(s.risk.level)}</span><span class="priority-arrow">↗</span></button>`).join('')}</div><a class="priority-footer" href="#alerts">Open response workspace →</a></section>`}
function sitesTable(rows,limit=100){return `<div class="table-wrap"><table><thead><tr><th>LOCATION / CORRIDOR</th><th>RISK LEVEL</th><th>RISK INDEX</th><th>ROAD STATUS</th><th>RAINFALL · 24H</th><th></th></tr></thead><tbody>${rows.slice(0,limit).map(s=>`<tr class="click-row"><td><button class="button ghost" data-action="site" data-id="${s.id}" style="padding:0;text-align:left;justify-content:start"><span><strong>${esc(s.name)}</strong><small>${esc(s.state)} · ${esc(s.road)}</small></span></button></td><td>${badge(s.risk.level)}</td><td><span class="score-inline">${s.risk.score}<span class="score-bar"><span style="width:${s.risk.score}%;background:${COLORS[s.risk.level]}"></span></span></span></td><td>${badge(s.road_status)}</td><td>${s.features.rainfall_24h} <small style="display:inline">mm</small></td><td><button class="icon-btn" data-action="site" data-id="${s.id}" aria-label="View ${esc(s.name)}">${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="6">No locations match your filters.</td></tr>'}</tbody></table></div>`}
function distribution(){return `<div class="distribution">${Object.entries(DATA.counts).map(([k,v])=>`<span title="${k}: ${v}" style="background:${COLORS[k]};width:${v/DATA.sites.length*100}%"></span>`).join('')}</div><div class="distribution-labels">${Object.entries(DATA.counts).map(([k,v])=>`<span>${k} <strong>${v}</strong></span>`).join('')}</div>`}
function overview(){const d=DATA.summary;return pageHead('A clearer view. An earlier response.','Monitor vulnerable slopes, understand the signals, coordinate the next move.',`${exportButton('sites')}<a class="button primary" href="#reports">${icon('plus')}New field report</a>`)+scenario()+`<div class="stats"><article class="stat"><div class="stat-label">Monitored locations ${icon('location')}</div><div class="stat-value">${d.sites}<small> / 8 states</small></div><div class="stat-foot"><span>●</span> Illustrative pilot network</div></article><article class="stat"><div class="stat-label">High & critical zones ${icon('activity')}</div><div class="stat-value">${DATA.counts.High+DATA.counts.Critical}<small> locations</small></div><div class="stat-foot warn"><span>●</span> Inspection prioritization required</div></article><article class="stat"><div class="stat-label">Active advisories ${icon('bell')}</div><div class="stat-value">${d.active_alerts}<small> in-app</small></div><div class="stat-foot"><span>●</span> Acknowledgement tracked</div></article><article class="stat"><div class="stat-label">Restricted road segments ${icon('road')}</div><div class="stat-value">${d.restricted_roads}<small> corridors</small></div><div class="stat-foot warn"><span>●</span> Demonstration access status</div></article></div><div class="main-grid">${mapPanel()}${priorityPanel()}</div><div class="lower-grid"><section class="panel"><div class="panel-head"><div><h2>Corridors on the watchlist</h2><p>Environmental signals and access conditions in one view</p></div><a class="panel-link" href="#map">View all locations ↗</a></div>${sitesTable([...DATA.sites].sort((a,b)=>b.risk.score-a.risk.score),4)}</section><section class="panel"><div class="panel-head"><div><h2>Regional risk profile</h2><p>Distribution of the current pilot scenario</p></div>${icon('activity')}</div><div class="trend"><div class="trend-values"><div><strong>${Math.round(DATA.sites.reduce((n,s)=>n+s.risk.score,0)/d.sites)}<small> / 100</small></strong><small>MEAN RISK INDEX</small></div><div><strong>${fmt(d.people_in_priority_zones)}</strong><small>ILLUSTRATIVE EXPOSURE</small></div></div><svg class="chart" viewBox="0 0 280 100" role="img" aria-label="Risk indices of sixteen pilot locations"><path class="chart-grid" d="M0 20h280 M0 45h280 M0 70h280 M0 95h280"/><path fill="#f0f5e9" d="M0 100 ${DATA.sites.map((s,i)=>`L${i*280/15} ${100-s.risk.score}`).join(' ')} L280 100Z"/><path class="chart-line" d="${DATA.sites.map((s,i)=>`${i?'L':'M'}${i*280/15} ${100-s.risk.score}`).join(' ')}"/></svg><div class="chart-labels"><span>Location 01</span><span>Location 08</span><span>Location 16</span></div>${distribution()}<p class="chart-legend"><i></i>Location comparison · not a time-series forecast</p></div></section></div><div class="insight-strip">${icon('shield')}<span><strong>Built for the last mile.</strong> Field observations stay on the device when connectivity drops and sync after reconnection.</span><a href="#reports">Open field workspace ↗</a></div>`}
function mapPage(){return pageHead('Every signal has a location.','Explore risk severity alongside roads, settlements and critical infrastructure.',`${refreshButton()}${exportButton('sites')}`)+scenario()+mapPanel(true)+`<section class="panel spacer"><div class="panel-head"><div><h2>Pilot location register</h2><p id="location-count">16 locations · illustrative road and exposure records</p></div><input class="search" id="site-search" type="search" placeholder="Search location or road…" aria-label="Search locations" style="max-width:250px"></div><div id="site-table">${sitesTable(DATA.sites)}</div></section>`}
function forecastPage(){return pageHead('See what changes the risk.','Test rainfall, terrain and soil conditions with an explainable hybrid model.',refreshButton(),'PREDICTIVE ANALYTICS')+scenario()+`<div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Scenario simulator</h2><p>Changes are calculated by the backend prediction engine</p></div>${icon('activity')}</div><div class="panel-body"><div class="field"><label for="sim-site">Start from a pilot location</label><select id="sim-site">${fieldsOptions('SG-01')}</select></div><div class="tabs"><button data-action="preset" data-preset="dry">Dry conditions</button><button data-action="preset" data-preset="monsoon">Monsoon</button><button data-action="preset" data-preset="extreme">Extreme rainfall</button></div><form id="sim-form">${[['rainfall_24h','Rainfall · last 24 hours','mm',0,600,230],['rainfall_72h','Rainfall · last 72 hours','mm',0,1800,610],['soil_moisture','Soil saturation proxy','%',0,100,92],['slope','Slope angle','°',0,80,48],['past_incidents','Historical incident count','',0,50,9],['vegetation_loss','Vegetation loss proxy','%',0,100,42]].map(([k,label,unit,min,max,value])=>`<div class="field"><label for="${k}">${label}<output id="out-${k}">${value}${unit}</output></label><input id="${k}" name="${k}" type="range" min="${min}" max="${max}" value="${value}" data-unit="${unit}"></div>`).join('')}<button class="button primary" type="submit">${icon('activity')}Recalculate risk</button></form><p class="form-note">Soil and vegetation values are scenario proxies. The index is not a calibrated probability of a landslide.</p></div></section><div><section class="panel"><div class="panel-head"><h2>Prediction & contributing factors</h2><span class="badge low">Hybrid model</span></div><div class="panel-body" id="prediction-result"></div></section><section class="panel spacer"><div class="panel-head"><div><h2>Weather context</h2><p>Fetch current modelled rainfall independently of the demo</p></div>${icon('rain')}</div><div class="panel-body"><div class="field"><label for="weather-site">Weather location</label><select id="weather-site">${fieldsOptions('SG-01')}</select></div><button class="button" data-action="weather">${icon('refresh')}Fetch weather model</button><div id="weather-result"><p class="form-note">Open-Meteo is an optional public weather source. No IMD feed or physical sensors are connected.</p></div></div></section></div></div>`}
function reportCards(rows){return rows.map(r=>`<article class="report-card"><div class="card-top"><span>${esc(r.id.slice(0,15))}</span>${badge(r.status)}</div><div><h3>${esc(r.type)}</h3><p>${esc(site(r.site_id)?.name||r.site_id)} · ${esc(site(r.site_id)?.state||'NER')}</p></div><p>${esc(r.note)}</p><span class="coords">${icon('location')} ${Number(r.lat).toFixed(4)}, ${Number(r.lon).toFixed(4)} · ${timeLabel(r.created_at)}</span>${r.review_note?`<p><strong>Review:</strong> ${esc(r.review_note)}</p>`:''}<div class="button-row"><button class="button" data-action="evidence" data-id="${esc(r.id)}">${icon('image')}Evidence</button>${authority()&&r.status==='Pending'?`<button class="button" data-action="review" data-id="${esc(r.id)}">${icon('check')}Review report</button>`:''}</div></article>`).join('')||'<div class="empty">No reports match this status.</div>'}
function reportsPage(){return pageHead('Ground truth starts here.','Capture a local observation. Keep it offline. Sync it when the network returns.',`<span class="queue-pill" id="queue-count">Checking offline queue…</span><button class="button" data-action="sync">${icon('refresh')}Sync queue</button><button class="button primary" data-action="new-report">${icon('plus')}New field report</button>`,'FIELD OPERATIONS')+scenario()+`<div class="tabs" id="report-tabs">${['All','Pending','Verified','Rejected'].map((v,i)=>`<button class="${i===0?'active':''}" data-action="report-filter" data-status="${v}">${v}${v==='All'?` · ${DATA.reports.length}`:''}</button>`).join('')}</div><div class="cards" id="report-cards">${reportCards(DATA.reports)}</div><div class="insight-strip">${icon('wifi')}<span><strong>Offline-first reporting.</strong> This device stores queued observations in IndexedDB. Uploads use idempotency IDs to prevent duplicate records. Sign in once before heading offline.</span></div>`}
const MESSAGES={en:(s)=>`Landslide risk advisory: ${s.name}, ${s.state}. Risk level: ${s.risk.level}. Avoid unstable slopes and follow verified district instructions. Demonstration message.`,hi:s=>`भूस्खलन जोखिम सूचना: ${s.name}, ${s.state}। जोखिम: ${s.risk.level}। अस्थिर ढलानों से दूर रहें और जिला प्रशासन के सत्यापित निर्देशों का पालन करें। यह प्रदर्शन संदेश है।`,as:s=>`ভূমিস্খলনৰ আশংকাৰ জাননী: ${s.name}, ${s.state}। বিপদৰ স্তৰ: ${s.risk.level}। অস্থিৰ ঢালৰ পৰা আঁতৰি থাকক আৰু জিলা প্ৰশাসনৰ নিৰ্দেশ মানি চলক। এইটো প্ৰদৰ্শনী বাৰ্তা।`};
function alertRows(rows){return rows.map(a=>`<article class="alert-card"><div class="alert-icon">${icon('bell')}</div><div><h3>${esc(a.location)} <span style="font-size:10px;font-weight:400">· ${esc(a.state)}</span></h3><span>${badge(a.level)} <span style="font-size:9px;color:#9ba58c">${a.score}/100 risk index</span></span><p>${esc(a.message)}</p><small>${timeLabel(a.created_at)} · ${esc(a.assignee||'District control room')} · ${esc(a.id)}</small><p style="font-size:9px">${esc(a.delivery||'In-app demonstration advisory · No SMS sent')}</p>${a.note?`<p><strong>Latest response:</strong> ${esc(a.note)}</p>`:''}${authority()&&a.status!=='Closed'?`<div class="button-row">${(a.status==='Open'?['Acknowledged']:a.status==='Acknowledged'?['Dispatched','Closed']:['Closed']).map(v=>`<button class="button" data-action="alert-update" data-id="${esc(a.id)}" data-status="${v}">${icon('check')}${{Acknowledged:'Acknowledge',Dispatched:'Dispatch team',Closed:'Close advisory'}[v]}</button>`).join('')}</div>`:''}</div>${badge(a.status)}</article>`).join('')||'<div class="empty">No advisories match this filter.</div>'}
function alertsPage(){return pageHead('From warning to coordinated action.','Assign ownership and track every advisory through acknowledgement and closure.',`${exportButton('alerts')}<button class="button primary" data-action="new-alert">${icon('plus')}Create advisory</button>`,'RESPONSE COORDINATION')+scenario()+`<div class="tabs" id="alert-tabs">${['All','Open','Acknowledged','Dispatched','Closed'].map((v,i)=>`<button class="${i===0?'active':''}" data-action="alert-filter" data-status="${v}">${v}</button>`).join('')}</div><section class="panel" id="alert-list">${alertRows(DATA.alerts)}</section><div class="insight-strip">${icon('shield')}<span><strong>Human oversight, always.</strong> In-app advisories are demonstration records. Official evacuation orders, SMS dissemination and agency integrations require authorized deployment.</span></div>`}
function sourcesPage(){return pageHead('Trust begins with provenance.','Understand the data, the model and the boundary between a prototype and an operational system.',`<a class="button" href="/docs" target="_blank" rel="noopener">${icon('database')}API reference ↗</a>`,'PLATFORM TRANSPARENCY')+scenario()+`<div class="source-list">${[
 ['rain','Weather model','Open-Meteo modelled precipitation and shallow soil moisture. Optional on-demand requests with a 15-minute cache.','Available on demand','low'],
 ['location','Terrain & historical records','16 illustrative locations, scenario slope angles, historical counts and exposure estimates. Not a surveyed GIS inventory.','Demonstration data','moderate'],
 ['image','Satellite context','Esri satellite basemap for visual context. Vegetation-loss values are illustrative inputs; satellite change detection is not connected.','Basemap only','moderate'],
 ['database','Sensor & ingestion API','Validated authenticated ingestion accepts sensor, manual and satellite-derived feature records. No physical sensor network connected.','API implemented','low'],
 ['bell','Warning dissemination','In-app advisories, role-based review and acknowledgement workflow are implemented. SMS delivery is not enabled.','In-app active','low'],
 ['globe','Official agency feeds','IMD, GSI, Bhuvan and NDMA feeds require permission, appropriate datasets and operational validation. This prototype is independent.','Not connected','moderate']
 ].map(([i,t,p,b,c])=>`<article class="source-card">${icon(i)}<div><h3>${t}</h3><p>${p}</p><span class="badge ${c}">${b}</span></div></article>`).join('')}</div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Model card · rf-demo-1.0</h2><p>Random Forest + transparent weighted baseline</p></div>${icon('activity')}</div><div class="panel-body" id="model-card"><span class="spinner"></span></div></section><section class="panel"><div class="panel-head"><div><h2>Operational readiness</h2><p>What the prototype does and what a pilot needs</p></div>${icon('shield')}</div><div class="panel-body"><ul class="check-list"><li><b>Implemented:</b> GIS, validated risk API, role checks, offline queue, evidence storage, review and audit trail.</li><li><b>Validation needed:</b> district rainfall thresholds, geotechnical labels and time-separated evaluation on real incidents.</li><li><b>GIS needed:</b> surveyed DEM/slope layers, official road connectivity and verified settlement exposure.</li><li><b>Agency rollout:</b> IMD/GSI data agreements, SMS provider credentials, authorized recipients and human response SOPs.</li><li><b>Storage:</b> PostgreSQL supported via DATABASE_URL. SQLite fallback is suitable for local demos; free Render filesystems are ephemeral.</li></ul><div class="button-row"><button class="button" data-action="audit">${icon('clock')}View audit trail</button>${USER?.role==='admin'?'<button class="button" data-action="ingest">Ingest observation</button>':''}</div></div></section></div>`}
function briefingPage(){return pageHead('The project, at a glance.','A presentation-ready walkthrough of the problem, solution and working prototype.',`<button class="button" data-action="print">${icon('download')}Print briefing</button><button class="button primary" data-action="present">${icon('presentation')}Presentation mode</button>`,'SMART INDIA HACKATHON · SIH26001')+`<button class="button exit-presentation" data-action="exit-present">Exit presentation ×</button><section class="brief-hero"><p class="eyebrow">SLOPEGUARD NER · MDoNER PROBLEM STATEMENT</p><h2>Earlier signals.<br>Clearer decisions.<br>More resilient communities.</h2><p>An AI-assisted landslide monitoring and response platform for the North Eastern Region. Environmental intelligence meets offline field reporting and accountable response.</p><div class="button-row"><a class="button lime" href="#overview">Explore the dashboard →</a><a class="button ghost" style="color:#c4d8bd" href="#forecast">Try the risk simulator ↗</a></div></section><div class="content-grid"><section class="panel"><div class="panel-head"><h2>The exact problem</h2>${icon('flag')}</div><div class="panel-body body-text">Rainfall, steep terrain, fragile geology and hill cutting create changing landslide risk. Separate weather records, field reports and road information make early decisions difficult. SIH26001 asks for integrated predictive analytics, GIS, community reports, multilingual alerts and offline operation.<p><a class="panel-link" href="https://sih.gov.in/sih2026PS" target="_blank" rel="noopener">Read the official SIH problem list ↗</a></p></div></section><section class="panel"><div class="panel-head"><h2>Our solution</h2>${icon('shield')}</div><div class="panel-body body-text">A single workflow connects location risk to action. The model explains the main environmental drivers; the map shows the affected corridor; field observations add local evidence; officials verify reports and manage advisories with a complete audit trail.<p><b style="color:#799364">Prototype boundary:</b> synthetic model training and illustrative terrain; no official warning authority or physical sensor deployment.</p></div></section></div><p class="eyebrow spacer">THE END-TO-END WORKFLOW</p><div class="step-list">${[
 ['Collect & validate','Standardize rainfall, moisture, slope, vegetation and incident features at each pilot location.'],
 ['Estimate & explain','Combine a rule-based baseline with a Random Forest model. Show the risk category and factor contributions.'],
 ['Map the impact','Visualize the risk footprint, illustrative roads, settlements and infrastructure.'],
 ['Capture field evidence','Submit geo-tagged observations with photo/video evidence. Queue locally during network loss.'],
 ['Verify & coordinate','Officials review reports, acknowledge advisories, assign a response team and track closure.'],
 ['Learn & improve','Retain observations and audit history. Replace synthetic training with validated historical inventories.']
 ].map(([h,p])=>`<article class="step"><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><div class="content-grid"><section class="panel"><div class="panel-head"><h2>A five-minute demonstration</h2>${icon('presentation')}</div><div class="panel-body"><ol class="body-text"><li>Open Overview and inspect the highest-risk location.</li><li>Change rainfall in the simulator and explain the drivers.</li><li>Enter the Field demo workspace and submit an observation.</li><li>Switch to the Official demo workspace and verify it.</li><li>Acknowledge an advisory, dispatch a team and show the audit log.</li><li>Explain provenance and the steps required for a real pilot.</li></ol></div></section><section class="panel"><div class="panel-head"><h2>Architecture & contribution</h2>${icon('layers')}</div><div class="panel-body body-text"><p><b>Browser / PWA</b> · Responsive GIS, IndexedDB offline queue, cached application shell.</p><p><b>FastAPI backend</b> · Authentication, role enforcement, ingestion, analytics and response workflow.</p><p><b>Prediction engine</b> · Scikit-learn Random Forest + 65/35 rule/model hybrid.</p><p><b>Storage & deployment</b> · PostgreSQL support, SQLite local fallback, GitHub source and Render service.</p><p><b>Distinctive focus</b> · Explainable risk → local evidence → verified response, with explicit data provenance.</p></div></section></div><section class="panel spacer"><div class="panel-head"><h2>Bibliography & data references</h2></div><div class="panel-body body-text"><p><a href="https://sih.gov.in/sih2026PS" target="_blank" rel="noopener">SIH 2026 · SIH26001 official problem statement ↗</a></p><p><a href="https://bhusanket.gsi.gov.in/Activities_V9.html" target="_blank" rel="noopener">Geological Survey of India · Landslide studies and warning research ↗</a></p><p><a href="https://open-meteo.com/en/docs" target="_blank" rel="noopener">Open-Meteo · Weather Forecast API documentation ↗</a></p><p>Map data © OpenStreetMap contributors · Satellite imagery © Esri and its data providers. Model benchmark is synthetic and does not establish real-world predictive performance.</p></div></section>`}

function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="modal-close" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){$('#modal').close()}
function loginModal(){if(USER){modal('Your workspace',`<p class="body-text">Signed in as <strong>${esc(USER.email)}</strong><br>Role: ${esc(USER.role)}</p><p class="form-note">Demo roles operate on the shared demonstration dataset. The administrator role requires a separate deployment secret.</p><button class="button" data-action="logout">Sign out</button>`);return}modal('Enter your workspace',`<p class="body-text">Sign in to capture observations or coordinate a response.</p><form id="login-form"><div class="field"><label for="login-email">Email address</label><input id="login-email" name="email" type="email" required autocomplete="username" placeholder="you@example.com"></div><div class="field"><label for="login-password">Password</label><input id="login-password" name="password" type="password" required autocomplete="current-password" minlength="8"></div><p id="login-error" class="form-note error" hidden></p><button class="button primary" type="submit">Sign in ${icon('arrow')}</button></form><p class="form-note">Explore the shared sample workspace with a demo role:</p><div class="login-options"><button data-action="demo-login" data-role="official">District official demo</button><button data-action="demo-login" data-role="field">Field officer demo</button><button data-action="demo-login" data-role="citizen">Citizen demo</button></div>`)}
function updateAccount(){const label=$('#account-label');if(USER){label.innerHTML=`${esc(USER.role[0].toUpperCase()+USER.role.slice(1))} workspace<small>${esc(USER.email)}</small>`;$('#top-account').textContent=USER.role[0].toUpperCase()}else{label.innerHTML='Guest workspace<small>Sign in for response tools</small>';$('#top-account').textContent='G'}}
async function signedIn(user){USER=user;localStorage.setItem('sg-user',JSON.stringify(user));updateAccount();closeModal();toast(`Signed in to the ${user.role} workspace`);await render();await syncQueue(false)}

function detailModal(id){const s=site(id);if(!s)return;modal(esc(s.name),`<p class="eyebrow">${esc(s.state)} · ${esc(s.district)} · ${esc(s.road)}</p>${badge(s.risk.level)} <span style="font-size:11px;color:#94a481">${s.risk.score}/100 demonstration index</span><div class="detail-grid">${[['24-hour rainfall',s.features.rainfall_24h,'mm'],['Soil saturation proxy',s.features.soil_moisture,'%'],['Terrain slope',s.features.slope,'°'],['Illustrative exposure',fmt(s.population),'people']].map(([h,v,u])=>`<div class="detail-cell"><small>${h}</small><strong>${v}</strong> <span>${u}</span></div>`).join('')}</div><p class="body-text">${esc(s.risk.action)}</p><h3>Why this index?</h3>${driversHTML(s.risk)}<p class="form-note">${esc(s.source)} · ${esc(s.satellite_status)}<br>Infrastructure: ${s.infrastructure.map(esc).join(', ')} · Road ${esc(s.road_status)}</p><div class="button-row"><button class="button primary" data-action="simulate-site" data-id="${id}">Explore scenario →</button>${authority()?`<button class="button" data-action="road" data-id="${id}">${icon('road')}Update road status</button>`:''}</div>`)}
function driversHTML(result){return result.drivers.map(d=>`<div class="driver"><span>${esc(({rainfall_24h:'24h rainfall',rainfall_72h:'72h rainfall',soil_moisture:'Soil proxy',slope:'Slope angle',past_incidents:'Past incidents',vegetation_loss:'Vegetation proxy'})[d.feature])}</span><span class="driver-bar"><b style="width:${d.contribution/30*100}%"></b></span><strong>${d.contribution}</strong></div>`).join('')}
function predictionHTML(r){return `<div class="risk-result"><span class="badge ${r.level.toLowerCase()}">${r.level} risk scenario</span><div class="risk-dial" style="border-top-color:${COLORS[r.level]};border-right-color:${COLORS[r.level]}"><strong>${r.score}</strong><small>RISK INDEX / 100</small></div><p>${esc(r.action)}</p></div>${driversHTML(r)}<div class="notice success">Rule baseline: ${r.rule_score}/100 · RF model output: ${r.model_score}/100<br>65% rule baseline + 35% RF output. Bars show baseline point contributions; they are not causal or SHAP explanations.</div><p class="form-note">${esc(r.limitation)}</p>`}
async function recalc(){if(!$('#sim-form'))return;const values=Object.fromEntries(new FormData($('#sim-form')));for(const k in values)values[k]=Number(values[k]);try{const r=await api('/predict',{method:'POST',body:JSON.stringify(values)});if($('#prediction-result'))$('#prediction-result').innerHTML=predictionHTML(r)}catch(e){if($('#prediction-result'))$('#prediction-result').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
function setSimulation(features){for(const [k,v] of Object.entries(features)){if($('#'+k)){$('#'+k).value=v;$('#out-'+k).textContent=v+$('#'+k).dataset.unit}}recalc()}

let dbPromise;
function offlineDB(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('slopeguard-offline',1);req.onupgradeneeded=()=>req.result.createObjectStore('queue',{keyPath:'client_id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return dbPromise}
async function queueOperation(action,value){const db=await offlineDB();return new Promise((resolve,reject)=>{const tx=db.transaction('queue',action==='getAll'?'readonly':'readwrite');const os=tx.objectStore('queue');const request=action==='getAll'?os.getAll():action==='delete'?os.delete(value):os.put(value);let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error)})}
async function updateQueueCount(){try{const rows=await queueOperation('getAll');const own=rows.filter(r=>r.owner===USER?.email);if($('#queue-count'))$('#queue-count').textContent=`${own.length} queued on this device`}catch{if($('#queue-count'))$('#queue-count').textContent='Offline storage unavailable'}}
let syncing=false;
async function syncQueue(notify=true){if(syncing)return;syncing=true;let count=0;try{if(!USER){if(notify)loginModal();return}if(!navigator.onLine){if(notify)toast('You are offline. Your saved reports remain on this device.');return}const rows=await queueOperation('getAll');for(const row of rows.filter(r=>r.owner===USER.email)){const {owner,...body}=row;await api('/reports',{method:'POST',body:JSON.stringify(body)});await queueOperation('delete',row.client_id);count++}if(notify||count)toast(count?`${count} field report${count===1?'':'s'} synchronized`:'No pending reports to sync');if(count)await loadData();if(count&&ROUTE==='reports')await render()}catch(e){if(notify)toast(`Reports remain queued: ${e.message}`)}finally{syncing=false;await updateQueueCount()}}
function newReport(){if(!USER){loginModal();return}modal('New field observation',`<p class="body-text">Record a warning sign near a pilot location. Your observation is queued on this device before upload.</p><form id="report-form"><div class="field"><label for="report-site">Nearest pilot location</label><select id="report-site" name="site_id">${fieldsOptions('SG-01')}</select></div><div class="form-row keep"><div class="field"><label for="report-lat">Latitude</label><input id="report-lat" name="lat" type="number" step="any" min="22" max="30" required value="${site('SG-01').lat}"></div><div class="field"><label for="report-lon">Longitude</label><input id="report-lon" name="lon" type="number" step="any" min="88" max="98" required value="${site('SG-01').lon}"></div></div><button type="button" class="button" data-action="geolocate">${icon('location')}Use my device location</button><p class="form-note">Coordinates initially match the selected pilot site. Device location is used only when you request it.</p><div class="field"><label for="report-type">Observation type</label><select id="report-type" name="type"><option>Cracks</option><option>Slope movement</option><option>Blocked road</option><option>Waterlogging</option><option>Other</option></select></div><div class="field"><label for="report-note">What did you observe?</label><textarea id="report-note" name="note" required minlength="10" maxlength="1500" placeholder="Describe the warning signs, road condition or visible movement…"></textarea></div><div class="field"><label for="report-file">Photo or video evidence (optional)</label><input id="report-file" type="file" accept="image/jpeg,image/png,video/mp4,video/webm"><small>JPEG, PNG, MP4 or WebM · maximum 5 MB. Use non-sensitive sample evidence in this shared demo.</small></div><p class="form-note" id="report-error"></p><button class="button primary" type="submit">${icon('flag')}Save observation</button></form>`)}
async function readFile(file){if(!file)return null;if(file.size>5*1024*1024)throw new Error('Choose evidence smaller than 5 MB');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read the evidence file'));reader.readAsDataURL(file)})}
function reviewModal(id){if(!authority()){loginModal();return}modal('Verify field evidence',`<form id="review-form" data-id="${esc(id)}"><p class="body-text">${esc(DATA.reports.find(r=>r.id===id)?.note)}</p><div class="field"><label for="review-status">Review outcome</label><select id="review-status" name="status"><option>Verified</option><option>Rejected</option></select></div><div class="field"><label for="review-note">Verification remarks</label><textarea id="review-note" name="note" minlength="5" maxlength="500" required placeholder="Record how the observation was checked…"></textarea></div><button class="button primary" type="submit">Save review</button></form>`)}
function newAlert(){if(!authority()){loginModal();return}modal('Create in-app advisory',`<p class="body-text">Publish a demonstration advisory for a selected pilot location. One active advisory is retained per location.</p><form id="alert-form"><div class="field"><label for="alert-site">Location</label><select id="alert-site" name="site_id">${fieldsOptions('SG-09')}</select></div><div class="field"><label for="alert-language">Message language</label><select id="alert-language" name="language"><option value="en">English</option><option value="hi">हिन्दी · Hindi</option><option value="as">অসমীয়া · Assamese</option></select></div><div class="field"><label for="alert-message">Advisory message</label><textarea id="alert-message" name="message" minlength="10" maxlength="1000" required>${esc(MESSAGES.en(site('SG-09')))}</textarea></div><p class="form-note">Published in the app only. SMS is not connected. Review all translations before operational use.</p><button class="button primary" type="submit">Publish in-app advisory</button></form>`)}
function alertUpdate(id,status){modal(`${{Acknowledged:'Acknowledge advisory',Dispatched:'Dispatch response team',Closed:'Close advisory'}[status]}`,`<form id="alert-update-form" data-id="${esc(id)}" data-status="${status}"><div class="field"><label for="response-assignee">Responsible team</label><input id="response-assignee" name="assignee" required minlength="3" maxlength="100" value="District response team"></div><div class="field"><label for="response-note">Response remarks</label><textarea id="response-note" name="note" required minlength="5" maxlength="500" placeholder="Record the action and verification details…"></textarea></div><button class="button primary" type="submit">Confirm ${status.toLowerCase()}</button></form>`)}
function roadModal(id){modal('Update corridor access',`<p class="body-text">${esc(site(id).name)} · ${esc(site(id).road)}</p><form id="road-form" data-id="${id}"><div class="field"><label for="road-status">Road access status</label><select id="road-status" name="status">${['Open','Caution','Restricted'].map(v=>`<option ${site(id).road_status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="road-note">Official remarks</label><textarea id="road-note" name="note" required minlength="5" maxlength="500"></textarea></div><button class="button primary" type="submit">Save status</button></form>`)}
function ingestModal(){modal('Ingest a validated observation',`<p class="body-text">Administrator-only feature record ingestion. New high-risk readings generate an in-app advisory.</p><form id="ingest-form"><div class="field"><label for="ingest-site">Pilot location</label><select id="ingest-site" name="site_id">${fieldsOptions('SG-01')}</select></div><div class="field"><label for="ingest-json">Observation JSON</label><textarea id="ingest-json" name="features" required style="height:220px;font-family:monospace">${esc(JSON.stringify(site('SG-01').features,null,2))}</textarea></div><div class="field"><label for="ingest-source">Source</label><select id="ingest-source" name="source"><option>manual</option><option>sensor</option><option>satellite-derived</option></select></div><button class="button primary" type="submit">Validate & ingest</button></form>`)}

let baseLayer,markerLayer,roadLayer,infraLayer;
function filteredSites(){return DATA.sites.filter(s=>(activeFilters.state==='all'||s.state===activeFilters.state)&&(activeFilters.level==='all'||s.risk.level===activeFilters.level)&&(!activeFilters.query||`${s.name} ${s.road} ${s.state}`.toLowerCase().includes(activeFilters.query)))}
function setupMap(){if(!$('#risk-map'))return;if(!window.L){$('#risk-map').innerHTML='<div class="empty">Map library unavailable. All locations remain available in the register below.</div>';return}MAP=L.map('risk-map',{scrollWheelZoom:false,zoomControl:true}).setView([25.8,92.65],6);baseLayer=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:18}).addTo(MAP);baseLayer.on('tileerror',()=>{if(!$('.map-empty')&&$('#risk-map')){const n=document.createElement('div');n.className='map-empty';n.textContent='Basemap unavailable · pilot overlays remain interactive';$('#risk-map').append(n)}});markerLayer=L.layerGroup().addTo(MAP);roadLayer=L.layerGroup().addTo(MAP);infraLayer=L.layerGroup().addTo(MAP);L.control.layers(null,{'Risk zones & locations':markerLayer,'Illustrative roads':roadLayer,'Illustrative villages & infrastructure':infraLayer},{collapsed:true}).addTo(MAP);plotMap();setTimeout(()=>MAP?.invalidateSize(),50)}
function plotMap(){if(!MAP)return;markerLayer.clearLayers();roadLayer.clearLayers();infraLayer.clearLayers();const rows=filteredSites();for(const s of rows){const color=COLORS[s.risk.level];L.circle([s.lat,s.lon],{radius:6000+s.risk.score*180,color,weight:1,fillColor:color,fillOpacity:.11}).addTo(markerLayer);const marker=L.circleMarker([s.lat,s.lon],{radius:5.5,color:'#fff',weight:2,fillColor:color,fillOpacity:1}).addTo(markerLayer);marker.bindTooltip(`${esc(s.name)} · ${s.risk.level} ${s.risk.score}/100`);marker.on('click',()=>detailModal(s.id));L.polyline(s.geometry,{color:s.road_status==='Restricted'?'#d4857c':s.road_status==='Caution'?'#c9a675':'#8ba783',weight:3,opacity:.85,dashArray:s.road_status==='Restricted'?'5 4':null}).bindTooltip(`${esc(s.road)} · ${s.road_status} (illustrative segment)`).addTo(roadLayer);L.circleMarker([s.lat+.018,s.lon+.026],{radius:3,color:'#8094aa',weight:1,fillOpacity:.7}).bindTooltip(`Illustrative settlement near ${esc(s.name)}`).addTo(infraLayer);L.marker([s.lat-.015,s.lon+.018],{icon:L.divIcon({className:'infra-icon',html:'<span style="color:#739aa0;background:white;font-size:10px;border:1px solid #b6cccc;padding:1px 3px;border-radius:3px">+</span>',iconSize:[12,12]})}).bindTooltip('Illustrative primary health centre').addTo(infraLayer)}if(rows.length&& (activeFilters.state!=='all'||activeFilters.level!=='all'))MAP.fitBounds(L.latLngBounds(rows.map(s=>[s.lat,s.lon])).pad(.4),{maxZoom:9});else if(activeFilters.state==='all'&&activeFilters.level==='all')MAP.setView([25.8,92.65],6);if($('#site-table'))$('#site-table').innerHTML=sitesTable(rows);if($('#location-count'))$('#location-count').textContent=`${rows.length} locations · illustrative road and exposure records`}

async function loadData(){try{DATA=await api('/dashboard');localStorage.setItem('sg-public-snapshot',JSON.stringify(DATA));$('#report-count').textContent=DATA.reports.filter(r=>r.status==='Pending').length}catch(e){const cached=localStorage.getItem('sg-public-snapshot');if(!cached)throw e;DATA=JSON.parse(cached);toast('Using the last saved demonstration snapshot. Reconnect to update.')}}
async function render(){const currentRoute=location.hash.slice(1).split('?')[0]||'overview';ROUTE=TITLES[currentRoute]?currentRoute:'overview';if(MAP){MAP.remove();MAP=null}clearTimeout(chartTimer);activeFilters={state:'all',level:'all',query:''};$('#breadcrumb').textContent=TITLES[ROUTE];$$('nav>a').forEach(a=>a.classList.toggle('active',a.dataset.route===ROUTE));$('#sidebar').classList.remove('open');const views={overview,map:mapPage,forecast:forecastPage,reports:reportsPage,alerts:alertsPage,sources:sourcesPage,briefing:briefingPage};$('#main').innerHTML=views[ROUTE]();if(['overview','map'].includes(ROUTE))setupMap();if(ROUTE==='forecast')await recalc();if(ROUTE==='reports')await updateQueueCount();if(ROUTE==='sources'){try{MODEL=MODEL||await api('/model');if($('#model-card'))$('#model-card').innerHTML=`<p class="body-text">${MODEL.training_samples} training / ${MODEL.test_samples} held-out synthetic samples. The target labels are generated from rules with noise. These numbers assess software behavior on synthetic data only.</p><div class="model-metrics">${['precision','recall','f1'].map(k=>`<div class="metric"><strong>${MODEL[k]}</strong><small>${k.toUpperCase()} · SYNTHETIC</small></div>`).join('')}</div><p class="form-note">Holdout confusion matrix [TN, FP] / [FN, TP]: ${esc(JSON.stringify(MODEL.confusion_matrix))}. No operational accuracy, lead-time or event probability claim is made.</p><h3>Global RF feature importance</h3>${Object.entries(MODEL.importance).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="driver"><span>${esc(k.replaceAll('_',' '))}</span><span class="driver-bar"><b style="width:${v*100}%"></b></span><strong>${Math.round(v*100)}%</strong></div>`).join('')}`}catch(e){if($('#model-card'))$('#model-card').textContent=e.message}}}

async function weatherAction(button){button.disabled=true;const target=$('#weather-result');target.innerHTML='<p class="form-note"><span class="spinner"></span> Fetching the weather model…</p>';try{const data=await api('/weather/'+$('#weather-site').value);if(!$('#weather-result'))return;const values=data.forecast.map(x=>Number(x.precipitation||0));const max=Math.max(...values,1);target.innerHTML=`<div class="weather-summary"><div><strong>${data.rainfall_24h}<small style="font-size:11px"> mm</small></strong><span>MODELLED RAIN · 24H</span></div><div><strong>${data.rainfall_72h}<small style="font-size:11px"> mm</small></strong><span>MODELLED RAIN · 72H</span></div></div><div class="weather-bars" role="img" aria-label="Modelled rainfall for the next 24 hours">${data.forecast.map(x=>`<div style="height:${Math.max(Number(x.precipitation||0)/max*100,2)}%" title="${esc(x.time)} UTC: ${x.precipitation??'missing'} mm"></div>`).join('')}</div><div class="chart-labels"><span>Next hour</span><span>Next 24 hours (UTC)</span></div><p class="form-note">${esc(data.source)} · ${timeLabel(data.retrieved_at)}${data.stale?' · CACHED / STALE':''}<br>${esc(data.note)}</p><button class="button" data-action="apply-weather" data-r24="${data.rainfall_24h}" data-r72="${data.rainfall_72h}">Use rainfall in simulator →</button>`}catch(e){target.innerHTML=`<div class="notice error">${esc(e.message)}</div>`}finally{button.disabled=false}}

document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{
 if(a==='close')closeModal();
 else if(a==='site')detailModal(b.dataset.id);
 else if(a==='refresh'){b.disabled=true;await loadData();await render();toast('Workspace refreshed')}
 else if(a==='demo-login'){b.disabled=true;await signedIn(await api('/auth/login',{method:'POST',body:JSON.stringify({email:b.dataset.role+'@demo.slopeguard.app',password:'Demo@SlopeGuard26'})}))}
 else if(a==='logout'){await api('/auth/logout',{method:'POST',body:'{}'});USER=null;localStorage.removeItem('sg-user');updateAccount();closeModal();await render();toast('Signed out')}
 else if(a==='new-report')newReport();
 else if(a==='sync')await syncQueue();
 else if(a==='new-alert')newAlert();
 else if(a==='review')reviewModal(b.dataset.id);
 else if(a==='road')roadModal(b.dataset.id);
 else if(a==='ingest'){if(USER?.role==='admin')ingestModal();else loginModal()}
 else if(a==='alert-update')alertUpdate(b.dataset.id,b.dataset.status);
 else if(a==='report-filter'){const v=b.dataset.status;$$('#report-tabs button').forEach(t=>t.classList.toggle('active',t===b));$('#report-cards').innerHTML=reportCards(DATA.reports.filter(r=>v==='All'||r.status===v))}
 else if(a==='alert-filter'){const v=b.dataset.status;$$('#alert-tabs button').forEach(t=>t.classList.toggle('active',t===b));$('#alert-list').innerHTML=alertRows(DATA.alerts.filter(r=>v==='All'||r.status===v))}
 else if(a==='simulate-site'){const id=b.dataset.id;closeModal();if(ROUTE!=='forecast'){location.hash='forecast';const onRoute=()=>{if($('#sim-site')){$('#sim-site').value=id;setSimulation(site(id).features)}else setTimeout(onRoute,30)};onRoute()}else{$('#sim-site').value=id;setSimulation(site(id).features)}}
 else if(a==='preset'){const p={dry:[18,60,35,22,1,5],monsoon:[140,390,82,42,6,30],extreme:[340,980,98,57,12,65]}[b.dataset.preset];setSimulation(Object.fromEntries(['rainfall_24h','rainfall_72h','soil_moisture','slope','past_incidents','vegetation_loss'].map((k,i)=>[k,p[i]])))}
 else if(a==='weather')await weatherAction(b);
 else if(a==='apply-weather'){$('#rainfall_24h').value=b.dataset.r24;$('#rainfall_72h').value=b.dataset.r72;for(const k of ['rainfall_24h','rainfall_72h'])$('#out-'+k).textContent=$('#'+k).value+'mm';await recalc();toast('Weather rainfall applied. Terrain and soil remain illustrative scenario inputs.')}
 else if(a==='geolocate'){if(!navigator.geolocation)throw new Error('Geolocation is unavailable in this browser');b.disabled=true;navigator.geolocation.getCurrentPosition(p=>{b.disabled=false;$('#report-lat').value=p.coords.latitude.toFixed(6);$('#report-lon').value=p.coords.longitude.toFixed(6);toast('Location captured. Check that the observation is within NER.')},err=>{b.disabled=false;toast('Location was not available. You can enter coordinates manually.')},{timeout:15000,maximumAge:60000})}
 else if(a==='basemap'){if(!MAP)return;$$('[data-action="basemap"]').forEach(t=>t.classList.toggle('active',t===b));MAP.removeLayer(baseLayer);baseLayer=L.tileLayer(b.dataset.mode==='satellite'?'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}':'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:b.dataset.mode==='satellite'?'Tiles © Esri and data providers':'© OpenStreetMap contributors',maxZoom:18}).addTo(MAP)}
 else if(a==='export'){if(!authority()){loginModal();return}const r=await fetch('/api/export/'+b.dataset.kind);if(!r.ok)throw new Error('Please sign in as an official to export records');const url=URL.createObjectURL(await r.blob());const link=document.createElement('a');link.href=url;link.download=`slopeguard-${b.dataset.kind}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 else if(a==='audit'){const rows=await api('/audit');modal('Authority audit trail',`<div style="max-height:500px;overflow:auto">${rows.map(r=>`<p class="body-text" style="font-size:10px;border-bottom:1px solid #eef2e7;padding-bottom:10px"><strong>${esc(r.action)}</strong><br>${esc(r.actor)} · ${timeLabel(r.time)}<br>${esc(r.target)}</p>`).join('')||'<p class="body-text">No recorded actions yet.</p>'}</div>`)}
 else if(a==='evidence'){if(!USER){loginModal();return}const r=await fetch('/api/reports/'+encodeURIComponent(b.dataset.id)+'/evidence');if(!r.ok)throw new Error(r.status===404?'No evidence was attached to this report.':r.status===403?'This role cannot access this evidence.':'Please sign in to view evidence.');const blob=await r.blob();const url=URL.createObjectURL(blob);modal('Field evidence',blob.type.startsWith('video')?`<video class="evidence-img" src="${url}" controls></video>`:`<img class="evidence-img" src="${url}" alt="Uploaded field observation evidence">`);$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true})}
 else if(a==='print')window.print();
 else if(a==='present'){document.body.classList.add('presentation-mode');window.scrollTo(0,0)}
 else if(a==='exit-present')document.body.classList.remove('presentation-mode');
 }catch(err){toast(err.message);if(b.isConnected)b.disabled=false}
});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.id?.endsWith('form'))return;e.preventDefault();const button=$('[type="submit"]',form);if(button)button.disabled=true;try{const data=Object.fromEntries(new FormData(form));
 if(form.id==='login-form')await signedIn(await api('/auth/login',{method:'POST',body:JSON.stringify(data)}));
 else if(form.id==='sim-form')await recalc();
 else if(form.id==='report-form'){const evidence=await readFile($('#report-file').files[0]);const body={...data,lat:Number(data.lat),lon:Number(data.lon),client_id:crypto.randomUUID(),evidence,owner:USER.email};await queueOperation('put',body);closeModal();toast('Observation saved on this device');await syncQueue(false)}
 else if(form.id==='review-form'){await api('/reports/'+form.dataset.id,{method:'PATCH',body:JSON.stringify(data)});closeModal();await loadData();await render();toast('Field report reviewed')}
 else if(form.id==='alert-form'){const r=await api('/alerts',{method:'POST',body:JSON.stringify(data)});closeModal();await loadData();await render();toast(r.duplicate?'An active advisory already exists for this location':'In-app advisory published')}
 else if(form.id==='alert-update-form'){await api('/alerts/'+form.dataset.id,{method:'PATCH',body:JSON.stringify({...data,status:form.dataset.status})});closeModal();await loadData();await render();toast('Response workflow updated')}
 else if(form.id==='road-form'){await api('/roads/'+form.dataset.id,{method:'PATCH',body:JSON.stringify(data)});closeModal();await loadData();await render();toast('Corridor access status updated')}
 else if(form.id==='ingest-form'){data.features=JSON.parse(data.features);await api('/ingest',{method:'POST',body:JSON.stringify(data)});closeModal();await loadData();await render();toast('Observation ingested and risk recalculated')}
 }catch(err){if(form.id==='login-form'){$('#login-error').hidden=false;$('#login-error').textContent=err.message}else if(form.id==='report-form')$('#report-error').textContent=err.message;else toast(err.message)}finally{if(button?.isConnected)button.disabled=false}});
document.addEventListener('input',e=>{const el=e.target;if(el.type==='range'){const out=$('#out-'+el.id);if(out)out.textContent=el.value+el.dataset.unit;clearTimeout(chartTimer);chartTimer=setTimeout(recalc,350)}if(el.id==='site-search'){activeFilters.query=el.value.toLowerCase();plotMap()}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='state-filter'){activeFilters.state=el.value;plotMap()}if(el.id==='risk-filter'){activeFilters.level=el.value;plotMap()}if(el.id==='sim-site')setSimulation(site(el.value).features);if(el.id==='report-site'){$('#report-lat').value=site(el.value).lat;$('#report-lon').value=site(el.value).lon}if(['alert-language','alert-site'].includes(el.id))$('#alert-message').value=MESSAGES[$('#alert-language').value](site($('#alert-site').value));if(el.id==='ingest-site')$('#ingest-json').value=JSON.stringify(site(el.value).features,null,2)});
$('#account-button').addEventListener('click',loginModal);$('#top-account').addEventListener('click',loginModal);$('#help-button').addEventListener('click',()=>location.hash='briefing');$('#menu-button').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function network(){const n=$('#network');n.classList.toggle('offline',!navigator.onLine);n.innerHTML=`<b></b>${navigator.onLine?'Online':'Offline'}`}
window.addEventListener('online',()=>{network();syncQueue(false)});window.addEventListener('offline',network);window.addEventListener('hashchange',()=>{if(DATA)render().catch(e=>toast(e.message));window.scrollTo(0,0)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('presentation-mode');$('#sidebar').classList.remove('open')}});
async function boot(){icons();network();try{try{USER=await api('/auth/me')}catch{if(!navigator.onLine){try{USER=JSON.parse(localStorage.getItem('sg-user'))}catch{}}}updateAccount();await loadData();await render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});await syncQueue(false)}catch(err){$('#main').innerHTML=`<div class="empty"><h1>The workspace is temporarily unavailable.</h1><p>${esc(err.message)}</p><p>If the free service is starting, refresh after a moment.</p><button class="button primary" data-action="refresh">Try again</button></div>`}}
boot();
